<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class Mimportermodel extends CI_Model {    function saveInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['logistic'], '1', '', $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_LOGISTICS, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This importer already exists";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrUpdateData['logistic'], $VarId, $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_LOGISTICS, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This importer already exists";            }        }        return $ArrResult;    }    function fnGetInfo($VarData = '', $VarStatus = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('id,logistic,updatedby,status');        $this->db->from(KN_MASTER_LOGISTICS);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarData <> '') {            $ArrWhere['logistic'] = $VarData;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        $ArrWhere['type'] = '3';        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '', $VarCompanyId = '') {        $this->db->from(KN_MASTER_LOGISTICS);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['logistic'] = $VarData;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        $ArrWhere[] = "i.type = '3' ";        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function fnCount($VarForwardingagent = '', $VarStatus = '') {        $userInfo = fnGetUserLoggedInfo(1);        $ArrWhere = array();        if ($VarForwardingagent <> '') {            $ArrWhere[] = "logistic like '%" . $VarForwardingagent . "%' ";        }        if ($VarStatus <> '') {            $ArrWhere[] = "i.status=" . $VarStatus;        } else {            $ArrWhere[] = "i.status in(1,2)";        }        $ArrWhere[] = "i.type = '3' ";        $ArrWhere[] = "i.companyid = " . $userInfo['companyid'];        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSql = "SELECT count(1) as trec  FROM " . KN_MASTER_LOGISTICS . " AS i INNER JOIN " . KN_USERS . " AS u ON i.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSql)->row();        return $ObjRows->trec;    }    function fnList($VarForwardingagent = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $userInfo = fnGetUserLoggedInfo(1);        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('logistic', 'i.status', 'u.contactname', 'i.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'i.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) $VarLimitInfo = $offset . "," . $VarLimit;        $ArrWhere = array();        if ($VarForwardingagent <> '') {            $ArrWhere[] = "logistic like '%" . $VarForwardingagent . "%' ";        }        if ($VarStatus <> '') {            $ArrWhere[] = "i.status=" . $VarStatus;        } else {            $ArrWhere[] = "i.status in(1,2)";        }        $ArrWhere[] = "i.companyid = " . $userInfo['companyid'];        $ArrWhere[] = "i.type = '3' ";        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSqlLab = "SELECT i.id,logistic,u.contactname,i.dateupdated,i.status FROM " . KN_MASTER_LOGISTICS . " AS i INNER JOIN " . KN_USERS . " AS u ON i.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }}